Task: Determine how many slides in the provided PowerPoint mention crustaceans. Plan: 1) Extract visible text and notes from all slides, 2) Build a crustacean term list, 3) Search case-insensitively across slides, 4) Verify and finalize. I will start by extracting all text and notes. Python code to get slide texts:

import pptx

pptx_path = "/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/a3fbeb63-0e8c-4a11-bff6-0e3b484c3e9c.pptx"

def get_all_slide_texts(path):
    prs = pptx.Presentation(path)
    results = []
    for idx, slide in enumerate(prs.slides, start=1):
        texts = []
        for shape in slide.shapes:
            if hasattr(shape, "text") and shape.text:
                texts.append(shape.text)
        # notes
        if getattr(slide, "has_notes_slide", False) and slide.notes_slide and slide.notes_slide.notes_text_frame:
            note_txt = slide.notes_slide.notes_text_frame.text
            if note_txt:
                texts.append(note_txt)
        results.append({"slide": idx, "text": " ".join(texts)})
    return results

slide_texts = get_all_slide_texts(pptx_path)
for s in slide_texts:
    print(f"Slide {s['slide']}: {s['text']}")

